import numpy as np, sys
from rdkit import Chem
names = ['Ca','Cb','r1','r2','r3','r4','A','C','B','D','E','F','G','H','I','J','K','L']
idx = {n:i for i,n in enumerate(names)}
m = Chem.MolFromMolFile(sys.argv[1], removeHs=False)
pos = m.GetConformer().GetPositions()
A,C,B,D = [pos[idx[n]] for n in 'ACBD']
n = np.cross(C-A, D-B); n/=np.linalg.norm(n); c = (A+C)/2
def side(p): return np.dot(p-c, n)
for nm in ['G','J','K','F','H','I','L','E','Ca','Cb']:
    print(nm, round(side(pos[idx[nm]]),2))
for a in m.GetAtomWithIdx(idx['Ca']).GetNeighbors()+m.GetAtomWithIdx(idx['Cb']).GetNeighbors():
    if a.GetAtomicNum()==1: print('H on', names[[x.GetIdx() for x in a.GetNeighbors()][0]], round(side(pos[a.GetIdx()]),2))
EOF
python check.py opt.mol
